#Requires -RunAsAdministrator

param(
    [string]$Endpoint = "http://127.0.0.1:8000/agent/heartbeat",
    [string]$ObservationsEndpoint = "",
    [string]$AgentKey = "itcity-agent-local-2026-secure-key",
    [string]$TenantHost = "",
    [string]$AssetTag = "",
    [int]$BranchId = 1,
    [int]$IntervalSeconds = 30,
    [int]$InventoryIntervalHours = 24,
    [int]$NetworkDiscoveryIntervalMinutes = 10,
    [int]$NetworkDiscoverySampleLimit = 256,
    [int]$SnmpDiscoveryIntervalMinutes = 15,
    [int]$SnmpSampleLimit = 500,
    [string]$InstallRoot = "",
    [string]$ConfigPath = "",
    [string]$TaskName = "ITCity-HeartbeatAgent",
    [string]$TaskUser = "",
    [switch]$PromptForTaskCredential,
    [switch]$UseStartupTrigger,
    [switch]$AdvancedMode,
    [switch]$NonInteractive,
    [switch]$Uninstall
)

# Requerido en contexto PS2EXE donde System.Security no se carga automaticamente
Add-Type -AssemblyName System.Security -ErrorAction SilentlyContinue

$script:InstallerLogPath = Join-Path ([Environment]::GetFolderPath('CommonApplicationData')) 'ITCity\Agent\installer.log'

# Resuelve el directorio del script/EXE en el nivel de script (aquÃ­ $MyInvocation funciona correctamente).
$script:ScriptDirectory = $PSScriptRoot
if ([string]::IsNullOrWhiteSpace($script:ScriptDirectory)) {
    try {
        $execPath = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
        if (-not [string]::IsNullOrWhiteSpace($execPath)) {
            $script:ScriptDirectory = Split-Path -Path $execPath -Parent -ErrorAction SilentlyContinue
        }
    } catch { }
}

function Pause-BeforeExit {
    if (-not $NonInteractive) {
        try {
            [void](Read-Host "Presiona Enter para cerrar")
        } catch {
            # no-op
        }
    }
}

function Get-DefaultInstallRoot {
    if ([string]::IsNullOrWhiteSpace($env:ProgramData)) {
        throw "No se encontrÃ³ ProgramData para instalar el agente."
    }

    return Join-Path $env:ProgramData "ITCity\Agent"
}

function Protect-String([string]$PlainText) {
    if ([string]::IsNullOrWhiteSpace($PlainText)) {
        return $null
    }

    $plainBytes = [System.Text.Encoding]::UTF8.GetBytes($PlainText)
    $cipherBytes = [System.Security.Cryptography.ProtectedData]::Protect(
        $plainBytes,
        $null,
        [System.Security.Cryptography.DataProtectionScope]::LocalMachine
    )

    return [Convert]::ToBase64String($cipherBytes)
}

function Test-CancelInput([string]$Value) {
    if ([string]::IsNullOrWhiteSpace($Value)) {
        return $false
    }

    return $Value.Trim() -match '^(q|quit|exit|cancel|cancelar|salir)$'
}

function Throw-InstallCanceled {
    throw [System.OperationCanceledException]::new("Instalacion cancelada por el usuario.")
}

function Read-NonEmptyValue([string]$Prompt, [string]$DefaultValue = "") {
    while ($true) {
        $suffix = if ([string]::IsNullOrWhiteSpace($DefaultValue)) { "" } else { " [$DefaultValue]" }
        $value = Read-Host "$Prompt$suffix"
        if (Test-CancelInput $value) {
            Throw-InstallCanceled
        }
        if ([string]::IsNullOrWhiteSpace($value)) {
            $value = $DefaultValue
        }
        if (-not [string]::IsNullOrWhiteSpace($value)) {
            return $value.Trim()
        }
    }
}

function Read-OptionalValue([string]$Prompt, [string]$DefaultValue = "") {
    $suffix = if ([string]::IsNullOrWhiteSpace($DefaultValue)) { "" } else { " [$DefaultValue]" }
    $value = Read-Host "$Prompt$suffix"
    if (Test-CancelInput $value) {
        Throw-InstallCanceled
    }
    if ([string]::IsNullOrWhiteSpace($value)) {
        return $DefaultValue
    }
    return $value.Trim()
}

function Read-PositiveInt([string]$Prompt, [int]$DefaultValue) {
    while ($true) {
        $raw = Read-Host "$Prompt [$DefaultValue]"
        if (Test-CancelInput $raw) {
            Throw-InstallCanceled
        }
        if ([string]::IsNullOrWhiteSpace($raw)) {
            return $DefaultValue
        }

        $parsed = 0
        if ([int]::TryParse($raw, [ref]$parsed) -and $parsed -gt 0) {
            return $parsed
        }
    }
}

function Read-YesNo([string]$Prompt, [bool]$DefaultValue) {
    $defaultText = if ($DefaultValue) { "S" } else { "N" }
    while ($true) {
        $value = Read-Host "$Prompt [${defaultText}]"
        if (Test-CancelInput $value) {
            Throw-InstallCanceled
        }
        if ([string]::IsNullOrWhiteSpace($value)) {
            return $DefaultValue
        }

        switch -Regex ($value.Trim()) {
            '^(s|si|y|yes)$' { return $true }
            '^(n|no)$' { return $false }
        }
    }
}

function Get-CurrentUserId {
    if (-not [string]::IsNullOrWhiteSpace($env:USERDOMAIN)) {
        return "$env:USERDOMAIN\$env:USERNAME"
    }

    return $env:USERNAME
}

function Resolve-InstallerSettings {
    if ([string]::IsNullOrWhiteSpace($script:InstallRoot)) {
        $script:InstallRoot = Get-DefaultInstallRoot
    }

    if ([string]::IsNullOrWhiteSpace($script:ConfigPath)) {
        $script:ConfigPath = Join-Path $script:InstallRoot "agent-config.json"
    }

    if ($script:NonInteractive) {
        if ([string]::IsNullOrWhiteSpace($script:AgentKey)) {
            throw "En modo -NonInteractive debes indicar -AgentKey."
        }
        return
    }

    Write-Host "" 
    Write-Host "==================================================" -ForegroundColor Cyan
    Write-Host "  Instalador del agente ITCity" -ForegroundColor Green
    Write-Host "==================================================" -ForegroundColor Cyan
    Write-Host ""

    Write-Host "Modo simple: usa configuraciÃ³n predefinida y solo pide lo esencial." -ForegroundColor Yellow
    Write-Host "(usa -AdvancedMode para editar intervalos, discovery y configuraciÃ³n de tarea)" -ForegroundColor DarkGray
    Write-Host "(escribe 'q' y Enter en cualquier pregunta para cancelar)" -ForegroundColor DarkGray
    Write-Host ""

    if ($script:BranchId -le 0) {
        $script:BranchId = Read-PositiveInt "ID de sucursal" 1
    }

    $script:AssetTag = Read-OptionalValue "Asset tag / inventario (opcional)" $script:AssetTag

    if ([string]::IsNullOrWhiteSpace($script:AgentKey)) {
        $script:AgentKey = Read-OptionalValue "Agent key (TENANT_AGENT_INGEST_KEY)"
    }

    if ([string]::IsNullOrWhiteSpace($script:AgentKey)) {
        Throw-InstallCanceled
    }

    $configureAdvanced = $script:AdvancedMode
    if (-not $configureAdvanced) {
        $configureAdvanced = Read-YesNo "Â¿Configurar opciones avanzadas (intervalos/discovery/SNMP/tarea)?" $false
    }

    if ($configureAdvanced) {
        $script:Endpoint = Read-NonEmptyValue "Endpoint de heartbeat" $script:Endpoint
        $script:ObservationsEndpoint = Read-OptionalValue "Endpoint observaciones de red (opcional)" $script:ObservationsEndpoint
        $script:TenantHost = Read-OptionalValue "Tenant host (opcional para local)" $script:TenantHost
        $script:IntervalSeconds = Read-PositiveInt "Intervalo en segundos" $script:IntervalSeconds
        $script:InventoryIntervalHours = Read-PositiveInt "Inventario extendido cada cuantas horas" $script:InventoryIntervalHours
        $script:NetworkDiscoveryIntervalMinutes = Read-PositiveInt "Discovery de red cada cuantos minutos" $script:NetworkDiscoveryIntervalMinutes
        $script:NetworkDiscoverySampleLimit = Read-PositiveInt "Maximo de dispositivos discovery por ciclo" $script:NetworkDiscoverySampleLimit
        $script:SnmpDiscoveryIntervalMinutes = Read-PositiveInt "Discovery SNMP cada cuantos minutos" $script:SnmpDiscoveryIntervalMinutes
        $script:SnmpSampleLimit = Read-PositiveInt "Maximo SNMP por target" $script:SnmpSampleLimit

        if ([string]::IsNullOrWhiteSpace($script:TaskUser) -and -not $script:PromptForTaskCredential) {
            $script:PromptForTaskCredential = Read-YesNo "Â¿Configurar con un usuario/password especificos para la tarea?" $false
        }

        if (-not $script:UseStartupTrigger) {
            $script:UseStartupTrigger = Read-YesNo "Â¿Ejecutar al arrancar Windows en vez de al iniciar sesion?" $false
        }
    }
}

function Install-AgentFiles {
    New-Item -ItemType Directory -Path $script:InstallRoot -Force | Out-Null
    $targetAgentScript = Join-Path $script:InstallRoot "windows-heartbeat-agent.ps1"

    # Agente embebido (base64 UTF-8) para no depender de archivos externos ni conexion HTTP
    $agentB64 = ""
    $agentBytes = [Convert]::FromBase64String($agentB64)
    [System.IO.File]::WriteAllBytes($targetAgentScript, $agentBytes)

    return $targetAgentScript
}

function Save-AgentConfig {
    $configDirectory = Split-Path -Path $ConfigPath -Parent
    if (-not [string]::IsNullOrWhiteSpace($configDirectory)) {
        New-Item -ItemType Directory -Path $configDirectory -Force | Out-Null
    }

    if ([string]::IsNullOrWhiteSpace($ObservationsEndpoint)) {
        if ($Endpoint -match '/agent/heartbeat/?$') {
            $ObservationsEndpoint = ($Endpoint -replace '/agent/heartbeat/?$', '/agent/network-observations')
        } else {
            $ObservationsEndpoint = $Endpoint
        }
    }

    $config = [ordered]@{
        endpoint = $Endpoint
        observations_endpoint = $ObservationsEndpoint
        tenant_host = $TenantHost
        asset_tag = $AssetTag
        branch_id = $BranchId
        interval_seconds = $IntervalSeconds
        inventory_interval_hours = $InventoryIntervalHours
        network_discovery_interval_minutes = $NetworkDiscoveryIntervalMinutes
        network_discovery_sample_limit = $NetworkDiscoverySampleLimit
        snmp_discovery_interval_minutes = $SnmpDiscoveryIntervalMinutes
        snmp_sample_limit = $SnmpSampleLimit
        snmp_targets = @()
        agent_key_protected = Protect-String $AgentKey
        installed_at = (Get-Date).ToString('s')
    }

    $config | ConvertTo-Json -Depth 5 | Set-Content -Path $ConfigPath -Encoding UTF8
}

function Register-AgentTask([string]$InstalledAgentScript) {
    $scriptArgs = "-ExecutionPolicy Bypass -NonInteractive -WindowStyle Hidden" +
        " -File `"$InstalledAgentScript`"" +
        " -ConfigPath `"$ConfigPath`""

    $action = New-ScheduledTaskAction -Execute "powershell.exe" -Argument $scriptArgs
    $settings = New-ScheduledTaskSettingsSet `
        -ExecutionTimeLimit (New-TimeSpan -Hours 0) `
        -RestartCount 3 `
        -RestartInterval (New-TimeSpan -Minutes 1) `
        -MultipleInstances IgnoreNew `
        -StartWhenAvailable

    $description = "Agente ITCity: envia metricas de rendimiento al servidor de monitoreo."

    if (Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue) {
        Stop-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue
        Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false
    }

    if ($PromptForTaskCredential -or -not [string]::IsNullOrWhiteSpace($TaskUser)) {
        $credential = $null
        if ([string]::IsNullOrWhiteSpace($TaskUser)) {
            $credential = Get-Credential -Message "Credenciales para ejecutar la tarea programada"
            $TaskUser = $credential.UserName
        } else {
            $securePassword = Read-Host "Password para $TaskUser" -AsSecureString
            $credential = New-Object System.Management.Automation.PSCredential($TaskUser, $securePassword)
        }

        $taskPassword = $credential.GetNetworkCredential().Password
        if ([string]::IsNullOrWhiteSpace($taskPassword)) {
            throw "No se recibiÃ³ password para registrar la tarea programada."
        }

        $trigger = if ($UseStartupTrigger) {
            New-ScheduledTaskTrigger -AtStartup
        } else {
            New-ScheduledTaskTrigger -AtLogOn -User $TaskUser
        }

        Register-ScheduledTask `
            -TaskName $TaskName `
            -Action $action `
            -Trigger $trigger `
            -Settings $settings `
            -Description $description `
            -User $TaskUser `
            -Password $taskPassword `
            -RunLevel Highest | Out-Null

        return [ordered]@{
            trigger = if ($UseStartupTrigger) { 'AtStartup' } else { "AtLogOn ($TaskUser)" }
            user = $TaskUser
        }
    }

    $currentUser = Get-CurrentUserId
    $trigger = if ($UseStartupTrigger) {
        New-ScheduledTaskTrigger -AtStartup
    } else {
        New-ScheduledTaskTrigger -AtLogOn -User $currentUser
    }
    $principal = New-ScheduledTaskPrincipal -UserId $currentUser -LogonType Interactive -RunLevel Highest

    Register-ScheduledTask `
        -TaskName $TaskName `
        -Action $action `
        -Trigger $trigger `
        -Settings $settings `
        -Principal $principal `
        -Description $description | Out-Null

    return [ordered]@{
        trigger = if ($UseStartupTrigger) { 'AtStartup' } else { "AtLogOn ($currentUser)" }
        user = $currentUser
    }
}

if ($Uninstall) {
    if (Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue) {
        Stop-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue
        Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false
        Write-Host "[OK] Tarea '$TaskName' eliminada." -ForegroundColor Green
    } else {
        Write-Host "[INFO] La tarea '$TaskName' no existe." -ForegroundColor Yellow
    }

    if (-not [string]::IsNullOrWhiteSpace($InstallRoot) -and (Test-Path $InstallRoot)) {
        Write-Host "[INFO] Los archivos en '$InstallRoot' se conservaron para evitar borrados no deseados." -ForegroundColor Yellow
    }
    Write-Host "Log: $script:InstallerLogPath" -ForegroundColor DarkGray
    Pause-BeforeExit
    exit 0
}

try {
    $logDir = Split-Path -Path $script:InstallerLogPath -Parent
    if (-not [string]::IsNullOrWhiteSpace($logDir)) {
        New-Item -ItemType Directory -Path $logDir -Force | Out-Null
    }
    Start-Transcript -Path $script:InstallerLogPath -Append -ErrorAction SilentlyContinue | Out-Null
} catch {
    # Si transcript falla, continuamos sin bloquear instalaciÃ³n.
}

try {
    Resolve-InstallerSettings

    if ([string]::IsNullOrWhiteSpace($AgentKey)) {
        throw "Debes indicar -AgentKey o capturarlo en el modo interactivo."
    }

    $installedAgentScript = Install-AgentFiles
    Save-AgentConfig
    $registration = Register-AgentTask -InstalledAgentScript $installedAgentScript
    if (-not (Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue)) {
        throw "La tarea '$TaskName' no quedÃ³ registrada en Task Scheduler."
    }

    Write-Host ""
    Write-Host "==================================================" -ForegroundColor Cyan
    Write-Host "  Agente instalado correctamente" -ForegroundColor Green
    Write-Host "==================================================" -ForegroundColor Cyan
    Write-Host "  Tarea      : $TaskName"
    Write-Host "  Script     : $installedAgentScript"
    Write-Host "  Config     : $ConfigPath"
    Write-Host "  Trigger    : $($registration.trigger)"
    Write-Host "  Usuario    : $($registration.user)"
    Write-Host "  Intervalo  : $IntervalSeconds segundos"
    Write-Host "  Inventario : cada $InventoryIntervalHours horas"
    Write-Host "  Discovery  : cada $NetworkDiscoveryIntervalMinutes minutos (max $NetworkDiscoverySampleLimit)"
    Write-Host "  SNMP       : cada $SnmpDiscoveryIntervalMinutes minutos (max $SnmpSampleLimit por target)"
    Write-Host "  Obs endpoint: $ObservationsEndpoint"
    Write-Host ""

    if (-not $NonInteractive) {
        $startNow = Read-YesNo "Â¿Iniciar el agente ahora?" $true
        if ($startNow) {
            Start-ScheduledTask -TaskName $TaskName
            Write-Host "[OK] Agente iniciado." -ForegroundColor Green
        }
    }

    Write-Host "Log: $script:InstallerLogPath" -ForegroundColor DarkGray
    Pause-BeforeExit
}
catch [System.OperationCanceledException] {
    Write-Host "[INFO] Instalacion cancelada." -ForegroundColor Yellow
    Write-Host "Log: $script:InstallerLogPath" -ForegroundColor DarkGray
    Pause-BeforeExit
    exit 2
}
catch {
    Write-Error $_.Exception.Message
    Write-Host "Log: $script:InstallerLogPath" -ForegroundColor DarkGray
    Pause-BeforeExit
    exit 1
}
finally {
    try {
        Stop-Transcript | Out-Null
    } catch {
        # no-op
    }
}
